import test from "node:test";
import assert from "node:assert/strict";
import {apply, planner} from "./replay.mjs";
import {readCatalog} from "./common/limits.mjs";

const request = {service:"studio", action:"book", id:"first", tenant:"orchid",
                 day:"2025-04-02", units:7};

test("Studio applies overrides, defaults, and independent tenant/day accounting", () => {
  const dispatch = planner(readCatalog());
  assert.deepEqual(dispatch(request), {status:"booked", id:"first", remaining:1});
  assert.deepEqual(dispatch({...request, id:"overflow", units:2}),
                   {status:"full", id:"overflow", remaining:1});
  assert.equal(dispatch({...request, id:"tomorrow", day:"2025-04-03"}).status, "booked");
  assert.equal(dispatch({...request, id:"unlisted", tenant:"iris", units:6}).status, "full");
  assert.equal(dispatch({...request, id:"unlisted", tenant:"iris", units:5}).status, "booked");
  assert.equal(dispatch({...request, service:"archive", units:6}).status, "full");
  assert.equal(dispatch({...request, service:"archive", units:5}).status, "booked");
});

test("Studio preserves replay, conflict, cancellation, imports and journal semantics", () => {
  const dispatch = planner(readCatalog());
  dispatch(request);
  assert.deepEqual(dispatch(request), {status:"replay", id:"first"});
  assert.equal(dispatch({...request, units:8}).status, "conflict");
  dispatch({...request, action:"import", id:"backfill", units:4});
  assert.equal(dispatch(request).status, "replay");
  assert.deepEqual(dispatch({...request, id:"overfull", units:1}),
                   {status:"full", id:"overfull", remaining:0});
  assert.deepEqual(dispatch({service:"studio", action:"usage", tenant:"orchid", day:request.day}),
                   {units:11});
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "cancelled");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch({...request, units:1}).status, "conflict");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "replay");
  assert.deepEqual(dispatch({...request, id:"replacement", units:4}),
                   {status:"booked", id:"replacement", remaining:0});
  const summary = dispatch({service:"studio", action:"summary"});
  assert.deepEqual(summary.occupied.map(row => row.id), ["backfill", "replacement"]);
  assert.equal(summary.events.length, 4);
});

test("renewals inherit Studio tenants and units and use the target day's allowance", () => {
  const dispatch = planner(readCatalog());
  dispatch(request);
  const renewal = {service:"studio", action:"renew", previous:"first", id:"may", day:"2025-05-02"};
  assert.deepEqual(dispatch(renewal), {status:"booked", id:"may", remaining:1});
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units:6}).status, "conflict");
  assert.deepEqual(dispatch({...renewal, id:"extra", units:2}),
                   {status:"full", id:"extra", remaining:1});
  assert.equal(dispatch({...renewal, id:"extra", units:1}).status, "booked");
  dispatch({service:"studio", action:"cancel", id:"may"});
  assert.equal(dispatch(renewal).status, "cancelled");
  dispatch({service:"studio", action:"cancel", id:"first"});
  assert.deepEqual(dispatch(renewal), {status:"missing", id:"first"});
  assert.deepEqual(dispatch({...renewal, previous:"absent"}), {status:"missing", id:"absent"});
});

test("lower Studio allocations, renewal defaults, and validation remain effective", () => {
  const catalog = {default:5, studios:new Map([["orchid", 3]])};
  const dispatch = planner(catalog);
  assert.equal(dispatch({...request, units:4}).status, "full");
  assert.equal(dispatch({...request, units:3}).status, "booked");
  assert.equal(dispatch({service:"studio", action:"renew", previous:"first", id:"next",
                         day:"2025-05-02", units:4}).status, "full");
  assert.equal(dispatch({...request, service:"archive", units:5}).status, "booked");
  assert.equal(dispatch({...request, id:"iris", tenant:"iris", units:5}).status, "booked");
  assert.equal(dispatch({service:"studio", action:"renew", previous:"iris", id:"iris-next",
                         day:"2025-05-02", units:6}).status, "full");
  assert.equal(dispatch({service:"archive", action:"renew", previous:"first", id:"archive-next",
                         day:"2025-05-02", units:6}).status, "full");
  assert.deepEqual(apply(dispatch, {...request, id:"invalid", units:0}), {status:"invalid", field:"units"});
  assert.deepEqual(apply(dispatch, {service:"studio", action:"renew", previous:"first", id:"bad",
                                  day:"2025-02-30"}), {status:"invalid", field:"day"});
});
