test("publication selects the inclusive audience window, not all projected cells", () => {
  assert.equal(projectCalendar(pilot, catalog).length, 12);
  assert.deepEqual(publicationCalendar(pilot, catalog), expected);
  assert.deepEqual(publicationCalendar({...pilot, window:{...pilot.window, from:"2025-04-03"}}, catalog),
                   [expected[1]]);
});

test("publication replays out-of-window sources and actions before selecting cells", () => {
  const source = {...pilot, operations:[
    {service:"studio", action:"import", id:"seed", tenant:"orchid", day:"2025-03-01", units:7},
    {service:"studio", action:"renew", previous:"seed", id:"renewed", day:"2025-04-02"},
    {service:"studio", action:"book", id:"cancelled", tenant:"orchid", day:"2025-04-03", units:8},
    {service:"studio", action:"cancel", id:"cancelled"},
    {service:"studio", action:"import", id:"overbooked", tenant:"orchid", day:"2025-04-03", units:10}
  ]};
  assert.deepEqual(publicationCalendar(source, catalog), [expected[0], {...expected[1], used:10, available:0}]);
